TLM.f("Tempora/Pasc7-0",{"officium":"Dominica Pentecostes","rule":["Gloria","Sequentia","Credo","Prefatio=Spiritu=hodierna die;"],"sections":{"Introitus":[{"k":"ref","la":"Sap 1:7"},{"k":"text","la":"Spíritus Dómini replévit orbem terrárum, allelúja: et hoc quod cóntinet ómnia, sciéntiam habet vocis, allelúja, allelúja, allelúja."},{"k":"ref","la":"Ps 67:2"},{"k":"text","la":"Exsúrgat Deus, et dissipéntur inimíci ejus: et fúgiant, qui odérunt eum, a fácie ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Spíritus Dómini replévit orbem terrárum, allelúja: et hoc quod cóntinet ómnia, sciéntiam habet vocis, allelúja, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, qui hodiérna die corda fidélium Sancti Spíritus illustratióne docuísti: da nobis in eódem Spíritu recta sápere; et de ejus semper consolatióne gaudére."},{"k":"macro","name":"Per Dominum eiusdem"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Acts 2:1-11"},{"k":"text","la":"Cum compleréntur dies Pentecóstes, erant omnes discípuli pariter in eódem loco: et factus est repénte de cœlo sonus, tamquam adveniéntis spíritus veheméntis: et replévit totam domum, ubi erant sedentes. Et apparuérunt illis dispertítæ linguæ tamquam ignis, sedítque supra síngulos eórum: et repléti sunt omnes Spíritu Sancto, et cœpérunt loqui váriis linguis, prout Spíritus Sanctus dabat éloqui illis. Erant autem in Jerúsalem habitántes Judǽi, viri religiósi ex omni natióne, quæ sub cœlo est. Facta autem hac voce, convénit multitúdo, et mente confúsa est, quóniam audiébat unusquísque lingua sua illos loquéntes. Stupébant autem omnes et mirabántur, dicéntes: Nonne ecce omnes isti, qui loquúntur, Galilǽi sunt? Et quómodo nos audívimus unusquísque linguam nostram, in qua nati sumus? Parthi et Medi et Ælamítæ et qui hábitant Mesopotámiam, Judǽam et Cappadóciam, Pontum et Asiam, Phrýgiam et Pamphýliam, Ægýptum et partes Líbyæ, quæ est circa Cyrénen, et ádvenæ Románi, Judǽi quoque et Prosélyti, Cretes et Arabes: audívimus eos loquéntes nostris linguis magnália Dei."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 103:30"},{"k":"text","la":"Emítte Spíritum tuum, et creabúntur, et renovábis fáciem terræ. Allelúja. (Hic genuflectitur)"},{"k":"text","la":"Veni, Sancte Spíritus, reple tuórum corda fidélium: et tui amóris in eis ignem accénde.","mark":"V"}],"Sequentia":[{"k":"text","la":"Veni, Sancte Spíritus,"},{"k":"text","la":"et emítte cǽlitus"},{"k":"text","la":"lucis tuæ rádium."},{"k":"sep"},{"k":"text","la":"Veni, pater páuperum;"},{"k":"text","la":"veni, dator múnerum;"},{"k":"text","la":"veni, lumen córdium."},{"k":"sep"},{"k":"text","la":"Consolátor óptime,"},{"k":"text","la":"dulcis hospes ánimæ,"},{"k":"text","la":"dulce refrigérium."},{"k":"sep"},{"k":"text","la":"In labóre réquies,"},{"k":"text","la":"in æstu tempéries,"},{"k":"text","la":"in fletu solácium."},{"k":"sep"},{"k":"text","la":"O lux beatíssima,"},{"k":"text","la":"reple cordis íntima"},{"k":"text","la":"tuórum fidélium."},{"k":"sep"},{"k":"text","la":"Sine tuo númine"},{"k":"text","la":"nihil est in hómine,"},{"k":"text","la":"nihil est innóxium."},{"k":"sep"},{"k":"text","la":"Lava quod est sórdidum,"},{"k":"text","la":"riga quod est áridum,"},{"k":"text","la":"sana quod est sáucium."},{"k":"sep"},{"k":"text","la":"Flecte quod est rígidum,"},{"k":"text","la":"fove quod est frígidum,"},{"k":"text","la":"rege quod est dévium."},{"k":"sep"},{"k":"text","la":"Da tuis fidélibus,"},{"k":"text","la":"in te confidéntibus,"},{"k":"text","la":"sacrum septenárium."},{"k":"sep"},{"k":"text","la":"Da virtútis méritum,"},{"k":"text","la":"da salútis éxitum,"},{"k":"text","la":"da perénne gáudium."},{"k":"text","la":"Amen. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 14:23-31"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Si quis díligit me, sermónem meum servábit, et Pater meus díliget eum, et ad eum veniémus et mansiónem apud eum faciémus: qui non díligit me, sermónes meos non servat. Et sermónem quem audístis, non est meus: sed ejus, qui misit me, Patris. Hæc locútus sum vobis, apud vos manens. Paráclitus autem Spíritus Sanctus, quem mittet Pater in nómine meo, ille vos docébit ómnia et súggeret vobis ómnia, quæcúmque díxero vobis. Pacem relínquo vobis, pacem meam do vobis: non quómodo mundus dat, ego do vobis. Non turbétur cor vestrum neque formídet. Audístis, quia ego dixi vobis: Vado et vénio ad vos. Si diligerétis me, gauderétis útique, quia vado ad Patrem: quia Pater major me est. Et nunc dixi vobis, priúsquam fiat: ut, cum factum fúerit, credátis. Jam non multa loquar vobíscum. Venit enim princeps mundi hujus, et in me non habet quidquam. Sed ut cognóscat mundus, quia díligo Patrem, et sicut mandátum dedit mihi Pater, sic fácio."}],"Offertorium":[{"k":"ref","la":"Ps 67:29-30"},{"k":"text","la":"Confírma hoc, Deus, quod operátus es in nobis: a templo tuo, quod est in Jerúsalem, tibi ófferent reges múnera, allelúja."}],"Secreta":[{"k":"text","la":"Múnera, quǽsumus, Dómine, obláta sanctífica: et corda nostra Sancti Spíritus illustratióne emúnda."},{"k":"macro","name":"Per Dominum eiusdem"}],"Communio":[{"k":"ref","la":"Act 2:2; 2:4"},{"k":"text","la":"Factus est repénte de cœlo sonus, tamquam adveniéntis spíritus veheméntis, ubi erant sedéntes, allelúja: et repléti sunt omnes Spíritu Sancto, loquéntes magnália Dei, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Sancti Spíritus, Dómine, corda nostra mundet infúsio: et sui roris íntima aspersióne fecúndet."},{"k":"macro","name":"Per Dominum eiusdem"}]},"hr":{"5974381bae9f3f59":{"t":"Mudr 1, 7, Ps 67, 2\n(Mudr 1, 7) Duh Gospodnji napuni svemir, <i>aleluja</i>!\nOn koji sve obuhvaća, poznaje svaki govor, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 67, 2) Nek ustane Bog i neka se rasprše njegovi neprijatelji! I neka bježe od njegova lica svi koji ga mrze.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Mudr 1, 7) Duh Gospodnji napuni svemir, <i>aleluja</i>!\nOn koji sve obuhvaća, poznaje svaki govor, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Mudr. 1, 7). Duh Gospodnji napunja svemir, Aleluja; i onaj, koji sve obuhvaća, čuje svaku riječ, Aleluja, Aleluja, Aleluja. (Ps. 67, 2) Nek ustane Bog i nek se razaspu neprijatelji njegovi i neka pobjegnu od lica njegova, koji mrze na nj. Slava Ocu . . . Duh Gospodnji.","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"},"221af66c071bf77a":{"t":"<i>Pomolimo se</i>.\nBože, koji si na današnji dan svjetlošću Duha Svetoga poučio srca vjernih, daj da u tom istom Duhu što je pravo spoznamo i njegovoj se utjehi vazda radujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si današnji dan svjetlošću Svetoga Duha poučio srca vjernih daj, da u istom Duhovi Duhu što je pravo mislimo i njegovoj se utjehi vazda radujemo. Po Gospodinu našem ... u jedinstvu istoga Duha . . .","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"},"8bcfa5f989a7fdf2":{"t":"Dj 2, 1-11\nČitanje Djela apostolskih. Kad se navršilo pedeset dana, svi su učenici bili zajedno na istome mjestu. I ujedanput ču se buka s neba, kao kad puše silan vjetar, te ispuni svu kuću gdje su bili. I ukažu im se odijeljeni ognjeni jezici i spusti se po jedan na svakoga od njih. Svi se napune Duha Svetoga i počnu govoriti različitim jezicima, kako im je Duh Sveti davao da govore. U Jeruzalemu je tada bilo pobožnih Židova iz svih naroda pod nebom. I kad se proču ta huka, skupi se mnogo ljudi i zapanje se jer ih je svaki pojedinac čuo gdje govore njegovim jezikom. Iznenađeni i začuđeni svi su pitali: Nisu li svi ovi što govore Galilejci? Pa kako svaki od nas čuje svoj materinski jezik? Parti i Međani, Elamljani i stanovnici Mezopotamije, Judeje i Kapadocije, Ponta i Azije, Frigije i Pamfilije, Egipta i libijskih krajeva oko Cirene, pridošlice Rimljani, Židovi i obraćenici, Krećani i Arapi, svi ih čujemo kako našim jezicima veličaju djela Božja.","kn":"Čitanje Djela apostolskih (2, 1-11). Kad su se navršili dani Pedesatke, bili su svi učenici zajedno na istomu mjestu. I najedamput ču se s neba huka kao kad duva silan vjetar, i napuni svu kuću, gdje su sjedili. I pojave im se razdijeljeni jezici kao od ognja i spuste se na pojedinoga od njih. I svi se napuniše Duha Svetoga i počeše govoriti tuđim jezicima, kako im je davao govoriti Duh Sveti. A u Jeruzalemu su boravili Židovi, pobožni ljudi od svakoga naroda pod nebom. I kad puče taj glas, skupi se mnogo naroda i smete se, jer ih je svaki pojedinac čuo govoriti svojim jezikom. Svi su se snebivali, čudili i pitali: Nijesu. li svi ovi, što govore, Gallejci? Kako da svaki od nas čuje svoj materinski jezik? Parćani i Međani i Klaraljani i stanovnici Mezopotamije, Judeje i Kapadocije, Ponta i Azije, Frigije i Pamfilije, Egipta i krajeva Libije, koja je kod Cirene, i pridošllce Rimljani, Židovi i obraćenici, Krećani i Arapi, čujemo ih da govore našim jezicima o divnim Božjim djelima.","knRef":"Kniewald 1942, str. 342–343 (snimka 172) (OCR)"},"3fa7ac0c6379c5a5":{"t":"Ps 103, 30\n<i>Aleluja</i>, <i>aleluja</i>.\nPošalji Duha svojega i postat će novi svijet i obnovit ćeš lice zemlje, <i>aleluja</i>.\n[Ovdje se poklekne] Dođi, Duše Sveti, napuni srca svojih vjernika i zapali u njima oganj svoje ljubavi."},"8986d237bd5894a0":{"t":"Dođi, duše presveti, /Sa neba nas posjeti /Zrakom svoje milosti. <i>\n</i>\nDođi, Oče ubogih,/Djelitelju dara svih,/Dođi, srca svjetlosti. <i>\n</i>\nTješitelju tako blag, /Ti nebeski Goste drag, /Pun miline hlade tih. <i>\n</i>\nUmornima odmore,/U vrućini lahore,/Razgovore žalosnih. <i>\n</i>\nSjaju svjetla blaženog,/Sjaj u srcu puka svog,/Napuni nam dušu svu. <i>\n</i>\nBez božanstva tvojega /Svi smo mi bez ičega,/Tonemo u crnom zlu. <i>\n</i>\nNečiste nas umivaj,/Suha srca zalivaj, /Vidaj rane ranjenim. <i>\n</i>\nMekšaj ćudi kamene,/ Zagrij grudi ledene,/Ne daj nama putem zlim. <i>\n</i>\nSvim što vjeru imaju,/Što se u te ufaju, /Sedam svojih dara daj. <i>\n</i>\nDaj nam krepost zaslužnu/I smrt lijepu, blaženu,/Daj vjekovit svima raj. <i>\n</i>\n<i>amen</i>, <i>aleluja</i>."},"f2fc741cdcf4d055":{"t":"Iv 14, 23-31\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus svojim učenicima: Tko me ljubi, slijedit će moju riječ. I njega će moj Otac ljubiti i k njemu ćemo doći i kod njega se nastaniti. Tko mene ne ljubi, ne slijedi moje riječi. A riječ koju ste čuli nije moja nego Oca koji me je poslao. Ovo sam vam govorio dok sam bio s vama. A Tješitelj Duh Sveti, kojega će vam Otac poslati u moje ime, poučit će vas o svemu i napomenut će vam sve što sam vam govorio. Mir vam ostavljam, mir svoj vam dajem, ali ga ne dajem onako kako svijet daje. Neka se ne uznemiruje i ne boji vaše srce! Čuli ste da sam vam rekao: Idem, ali ću vam opet doći. Da me ljubite, vi biste se radovali što idem Ocu, jer je Otac veći od mene. Kazao sam vam prije nego se to dogodi, da vjerujete kad se dogodi. Neću više s vama mnogo govoriti, jer dolazi poglavica ovoga svijeta, ali sa mnom on nema ništa. Neka svijet spozna da ljubim Oca i da radim kako mi je zapovjedio Otac.","kn":"t Slijedi sveto evanđelje po Ivanu (14, 23-31). U ono vrijeme reče Isus svojim učenicima: Tko mene ljubi, držat će moju riječ i ljubit će ga moj Otac; k njemu ćemo doći i nastanit ćemo se kod njega. Tko mene ne ljubi, ne drži mojih riječi. A riječ, koju ste čuli, nije moja, nego Oca, koji je mene poslao. Ovo sam vam govorio, dok sam bio s vama. A Utješitelj Duh Sveti, kojega ze Otac poslati u moje ime, poučit će vas o svemu i napomenut će vam sve, što sam vam ja rekao. Ostavljam vam svoj mir, dajem vam svoj mir, a ne dajem vam, kao što daje svijet. Neka se ne iplaši niti boji vaše srce! Ćuli ste, da sam vam ja kazao: Idem i doći ču k vama. Kad bi vi mene ljubili, svakako bi se radovali, što idem k Ocu, jer je Otac veći od mene. I rekao sam vam sada, prije nego se dogodi, da vjerujete, kada se dogodi. Ne ču više s vama mnogo govoriti, jer dolazi poglavica ovoga svijeta, ali na meni nema ništa, nego neka svijet pozna, da ljubim Oca i da tako radim, kako mi je zapovjedio Otac.","knRef":"Kniewald 1942, str. 342–343 (snimka 172) (OCR)"},"abc4ed74aaf19369":{"t":"Ps 67, 29-30\nUtvrdi ovo, Bože, što si učinio u nama! U svetom hramu tvojem, koji je u Jeruzalemu, kraljevi će ti donositi darove, <i>aleluja</i>.","kn":"(Ps. 67, 29, 30). Utvrdi, Bože, što si djelovao u nama; neka dođu kraljevi i prinesu Ti darove u Tvojem hramu u svetomu gradu.","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"8a23e3366dd2990d":{"t":"Posveti, molimo, Gospodine, prinesene darove a naša srca očisti svjetlošću Duha Svetoga.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, posveti prikazane darove 1 očisti naša srca prosviječenjem Duha Svetoga, po G. n, I. K.","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"e36be14714c3ff04":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. On uziđe nad sva nebesa, sjede uz tvoju desnu, te obećanog Duha Svetoga na današnji dan izli na posinjenu djecu. – Stoga sav svijet na krugu zemaljskom kliče zanosnom radošću, a i višnje sile i s njima anđeoske vlasti zajedno pjevaju pjesmu tvoje slave govoreći bez prestanka:"},"6f9359f735e1fb70":{"t":"Dj 2, 2 i 4\nUjedanput ču se buka s neba, kao kad puše silan vjetar, gdje su bili, <i>aleluja</i>.\nI svi se napune Duha Svetoga i stadoše veličati djela Božja, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Dj. ap. 2, 2, 4). Najedamput postade šum s neba kao da puše silan vjetar i napuni svu kuću. gdje su sjedili, Aleluja; i napuniše se svi Duha Svetoga naviještajući veličanstvena djela Božja. Aleluja, Aleluja.","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"0ed7897a863e81f5":{"t":"<i>Pomolimo se</i>.\nSrca naša, Gospodine, očistio dolazak Duha Svetoga i oplodio ih svojom nutarnjom rosom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, da dolazak Duha Svetoga očisti naša srca i oplodi ih nutarnjom blagošću svoje rose. Po G. n. I. K. ... u jedinstvu istoga Duha . . .","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"}}});
